import axios from "axios";
// const API_URL = "http://localhost:3000";
const API_URL = '/api';
export class APIService {
  constructor() {}

  // this is the part i'm working on
  sendContactEmail(mail_subject, mail_body) {
    const url = `${API_URL}/send-email`;

    return axios({
      method: "POST",
      url: url,
      headers: {
        "Content-Type": "application/json"
      },
      data: {
        subject: mail_subject,
        message: mail_body
      }
    }).then(function (res) {
      const data = res["data"];
      // data is the response
      return data;
    });
  }

  sendFormData(mail_subject, mail_body) {
    const url = `${API_URL}/form`;

    return axios({
      method: "POST",
      url: url,
      headers: {
        "Content-Type": "application/json"
      },
      data: {
        subject: mail_subject,
        message: mail_body
      }
    }).then(function (res) {
      const data = res["data"];
      // data is the response
      return data;
    });
  }
}