import Vue from 'vue'
import Router from 'vue-router'
import AccomodationVue from "./views/Accomodation.vue";
import DiningVue from "./views/Dining.vue";
import GalleryVue from "./views/Gallery.vue";
import ConferenceVue from "./views/Conference.vue";
import BookingVue from "./views/Booking.vue";
import BarVue from "./views/Bar.vue";
import AboutVue from "./views/About.vue";
import Home from "./views/Home.vue";
Vue.use(Router)

export default new Router({
  mode: 'history',
  base: process.env.BASE_URL,
  routes: [{
      path: '/',
      name: 'Home',
      component: Home
    },
    {
      path: '/about',
      name: 'about',
      component: AboutVue
    },
    {
      path: '/dining',
      name: 'Dining',
      component: DiningVue
    },
    {
      path: '/gallery',
      name: 'Gallery',
      component: GalleryVue
    },
    {
      path: '/conference',
      name: 'Conference',
      component: ConferenceVue
    },
    {
      path: '/lounge',
      name: 'Lounge',
      component: BarVue
    },
    {
      path: '/accomodation',
      name: 'Accomodation',
      component: AccomodationVue
    },
    {
      path: '/booking',
      name: 'Booking',
      component: BookingVue
    }
  ],
  scrollBehavior(to, from, savedPosition) {
    if (savedPosition) {
      return savedPosition
    } else {
      return {
        x: 0,
        y: 0
      }
    }
  },
})